// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.bus.BrainEventimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport java.time.Instantimport java.util.UUIDimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Layer 5: Agentic Orchestrator. * * Implements the ReAct (Reason + Act) pattern for complex, multi-step tasks: * * ``` * User: "Call mom and then send her a follow-up SMS" * * Step 1: Thought("I need to call mom first") *         Action(ToolCall("call_skill", {"contact": "mom"})) *         Observation(ToolSuccess("Calling mom...")) * * Step 2: Thought("Now I need to send a follow-up SMS to mom") *         Action(ToolCall("sms_skill", {"contact": "mom", "message": "Following up..."})) *         Observation(ToolSuccess("SMS sent")) * * Step 3: Thought("Both tasks done, I can now answer the user") *         Action(FinalAnswer("Done — called mom and sent the follow-up SMS.")) * ``` * * ## ReAct Loop * *   1. **Plan** — [AgenticPlanner] decides the next thought + action *   2. **Guardrail check** — [AgenticGuardrails] verifies max steps / cost / time / loop *   3. **Execute** — [AgenticExecutor] runs the action *   4. **Critique** — [AgenticCritic] evaluates the result *   5. **Record** — step added to [WorkflowTraceBuilder] *   6. **Repeat** — until critic says STOP or guardrails say STOP * * ## When Agentic Is Triggered * * The brain orchestrator (Step 2.8) calls this layer when: *   - Intent classifier detects [com.roshan.persona.brain.intent.Intent.MultiStep] *   - User explicitly says "agent:" or "plan:" prefix *   - Layers 0-4 couldn't handle the request (last resort) * * ## Guardrails * *   - Max 10 steps (default, configurable via [AgenticGuardrails]) *   - Max $0.50 cost per workflow (configurable) *   - Max 60 seconds (configurable) *   - Max 2 repeats of same tool call (loop detection) *   - Max 2 retries per failed step (critic decision) * * If any guardrail is hit, the workflow stops with the appropriate * [WorkflowStatus] and the trace is preserved for debugging. * * ## Privacy * *   - All tool calls stay on device (unless the tool itself is a cloud tool) *   - LLM queries scrubbed of PII before cloud calls *   - Workflow trace stored on device only, never synced *   - User can view + delete workflow history in Settings * * @see <a href="docs/spec/module2-spec-review.pdf">§9 Layer 5</a> */@Singletonclass AgenticOrchestrator @Inject constructor(    private val planner: AgenticPlanner,    private val executor: AgenticExecutor,    private val critic: AgenticCritic,    private val guardrails: AgenticGuardrails,    private val toolRegistry: AgenticToolRegistry,    private val brainBus: BrainBus,) {    /**     * Run an agentic workflow for [userInput].     *     * @param userInput the user's original request     * @param context the brain context     * @param onStep callback invoked after each step (for live UI updates)     * @return [Result] containing the [WorkflowTrace] (success) or error (failure)     */    suspend fun run(        userInput: String,        context: BrainContext,        onStep: (WorkflowStep) -> Unit = {},    ): Result<AgenticOutput> {        val startNanos = System.nanoTime()        val correlationId = context.correlationId        val workflowId = UUID.randomUUID().toString()        val traceBuilder = WorkflowTraceBuilder(            workflowId = workflowId,            correlationId = correlationId,            sessionId = context.sessionId,            userInput = userInput,        )        critic.reset()  // Reset retry tracking for this workflow        Timber.tag("NOUS.L5").i("Starting workflow %s for: %s", workflowId, userInput.take(80))        // ─── Check 1: Input safety (constitutional guardrails) ────────────        val inputSafety = critic.checkInputSafety(userInput)        if (inputSafety is GuardrailResult.Blocked) {            Timber.tag("NOUS.L5").w("Input blocked: %s", inputSafety.reason)            val trace = traceBuilder.build(                finalStatus = WorkflowStatus.FAILED,                finalAnswer = null,                failureReason = "Input blocked: ${inputSafety.reason}",            )            return Result.Success(                data = AgenticOutput(                    trace = trace,                    skillOutput = SkillOutput.Failure(                        error = AppError.Configuration.InvalidProviderConfig(                            reason = inputSafety.reason,                        ),                        userMessage = "I can't help with that request: ${inputSafety.reason}",                    ),                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        // ─── Check 2: Budget allows agentic at all ───────────────────────        if (!context.budget.allowAgentic) {            val trace = traceBuilder.build(                finalStatus = WorkflowStatus.FAILED,                finalAnswer = null,                failureReason = "Agentic execution not allowed in this budget",            )            return Result.Success(                data = AgenticOutput(                    trace = trace,                    skillOutput = SkillOutput.Failure(                        error = AppError.Configuration.InvalidProviderConfig(                            reason = "Agentic execution disabled in budget",                        ),                        userMessage = "I can't run a multi-step workflow right now. Try a simpler request.",                    ),                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        // Effective guardrails — combine defaults with budget        val effectiveGuardrails = guardrails.copy(            maxCostUsd = minOf(guardrails.maxCostUsd, context.budget.maxCostUsd),            maxDurationMs = minOf(guardrails.maxDurationMs, context.budget.maxLatencyMs),        )        val toolCatalog = if (context.deviceContext.isOnline) {            toolRegistry.getAll()        } else {            toolRegistry.getOfflineTools()        }        // ReAct loop        while (true) {            val elapsedMs = (System.nanoTime() - startNanos) / 1_000_000            val currentCost = traceBuilder.currentCost()            val stepCount = traceBuilder.stepCount()            // ─── Guardrail check ──────────────────────────────────────────            val guardrailDecision = effectiveGuardrails.check(                currentStepCount = stepCount,                currentCostUsd = currentCost,                elapsedMs = elapsedMs,            )            if (guardrailDecision is GuardrailDecision.Stop) {                Timber.tag("NOUS.L5").w("Guardrail stop: %s", guardrailDecision.reason)                // Best-effort partial answer extraction (spec §7)                val partialAnswer = extractPartialAnswer(traceBuilder.getSteps())                val trace = traceBuilder.build(                    finalStatus = guardrailDecision.status,                    finalAnswer = partialAnswer,                    failureReason = guardrailDecision.reason,                )                brainBus.emit(BrainEvent.BrainRequestFailed(                    error = AppError.Unknown(correlationId = correlationId),                    userMessage = "Workflow stopped: ${guardrailDecision.reason}",                    correlationId = correlationId,                ))                return Result.Success(                    data = AgenticOutput(                        trace = trace,                        skillOutput = if (partialAnswer != null) {                            SkillOutput.Partial(                                message = partialAnswer,                                warnings = listOf("Workflow stopped: ${guardrailDecision.reason}"),                            )                        } else {                            SkillOutput.Failure(                                error = AppError.Unknown(correlationId = correlationId),                                userMessage = "I couldn't complete this task: ${guardrailDecision.reason}",                            )                        },                    ),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            // ─── Plan ─────────────────────────────────────────────────────            val planResult = planner.planNext(                userInput = userInput,                toolCatalog = toolCatalog,                previousSteps = traceBuilder.getSteps(),                context = context,            )            val decision: PlannerDecision = when (planResult) {                is Result.Failure -> {                    Timber.tag("NOUS.L5").w("Planner failed: ${planResult.error.message}")                    // Best-effort partial answer extraction (spec §7)                    val partialAnswer = extractPartialAnswer(traceBuilder.getSteps())                    val trace = traceBuilder.build(                        finalStatus = WorkflowStatus.FAILED,                        finalAnswer = partialAnswer,                        failureReason = "Planner failed: ${planResult.error.message}",                    )                    return Result.Success(                        data = AgenticOutput(                            trace = trace,                            skillOutput = if (partialAnswer != null) {                                SkillOutput.Partial(                                    message = partialAnswer,                                    warnings = listOf("Planner failed — returning best-effort partial result."),                                )                            } else {                                SkillOutput.Failure(                                    error = planResult.error,                                    userMessage = "I couldn't figure out how to approach this task.",                                )                            },                        ),                        correlationId = correlationId,                        durationNanos = System.nanoTime() - startNanos,                    )                }                is Result.Success -> planResult.data                is Result.Partial -> planResult.data            }            // ─── Constitutional safety check (before execution) ───────────            val safetyResult = critic.checkSafety(decision.action)            if (safetyResult is GuardrailResult.Blocked) {                Timber.tag("NOUS.L5").w("Constitutional block: %s", safetyResult.reason)                val partialAnswer = extractPartialAnswer(traceBuilder.getSteps())                val trace = traceBuilder.build(                    finalStatus = WorkflowStatus.FAILED,                    finalAnswer = partialAnswer,                    failureReason = "Constitutional block: ${safetyResult.reason}",                )                return Result.Success(                    data = AgenticOutput(                        trace = trace,                        skillOutput = if (partialAnswer != null) {                            SkillOutput.Partial(                                message = partialAnswer,                                warnings = listOf("Blocked: ${safetyResult.reason}"),                            )                        } else {                            SkillOutput.Failure(                                error = AppError.Configuration.InvalidProviderConfig(                                    reason = safetyResult.reason,                                ),                                userMessage = "I can't do that: ${safetyResult.reason}",                            )                        },                    ),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            // ─── Loop detection (for tool calls) ──────────────────────────            if (decision.action is AgenticStep.ToolCall) {                val loopCheck = effectiveGuardrails.checkLoop(                    toolId = decision.action.toolId,                    params = decision.action.params,                    previousSteps = traceBuilder.getSteps(),                )                if (loopCheck is GuardrailDecision.Stop) {                    Timber.tag("NOUS.L5").w("Loop detected: %s", loopCheck.reason)                    val partialAnswer = extractPartialAnswer(traceBuilder.getSteps())                    val trace = traceBuilder.build(                        finalStatus = loopCheck.status,                        finalAnswer = partialAnswer,                        failureReason = loopCheck.reason,                    )                    return Result.Success(                        data = AgenticOutput(                            trace = trace,                            skillOutput = if (partialAnswer != null) {                                SkillOutput.Partial(                                    message = partialAnswer,                                    warnings = listOf("Loop detected — returning partial result."),                                )                            } else {                                SkillOutput.Failure(                                    error = AppError.Unknown(correlationId = correlationId),                                    userMessage = "I got stuck in a loop. Try rephrasing your request.",                                )                            },                        ),                        correlationId = correlationId,                        durationNanos = System.nanoTime() - startNanos,                    )                }            }            // ─── Execute ──────────────────────────────────────────────────            val stepStartNanos = System.nanoTime()            val stepNumber = traceBuilder.stepCount() + 1            val stepResult = executor.execute(decision.action, context)            // ─── Record ───────────────────────────────────────────────────            val stepDurationMs = (System.nanoTime() - stepStartNanos) / 1_000_000            val stepCost = when (stepResult) {                is AgenticStepResult.ToolSuccess -> stepResult.costUsd                is AgenticStepResult.ToolFailure -> stepResult.costUsd                is AgenticStepResult.LlmSuccess -> stepResult.costUsd                is AgenticStepResult.LlmFailure -> stepResult.costUsd                is AgenticStepResult.FinalAnswerProduced -> stepResult.costUsd            }            traceBuilder.recordStep(                thought = decision.thought,                action = decision.action,                observation = stepResult,                durationMs = stepDurationMs,                costUsd = stepCost,            )            // Notify live UI            val lastStep = traceBuilder.getSteps().last()            onStep(lastStep)            // ─── Critique ─────────────────────────────────────────────────            val criticDecision = critic.evaluate(                stepNumber = stepNumber,                step = decision.action,                result = stepResult,            )            when (criticDecision) {                is CriticDecision.Continue -> {                    // Loop continues — planner will decide next step                }                is CriticDecision.Retry -> {                    // Don't advance — same step will be re-planned                    // (Actually, planner sees previous steps, so it will likely                    // produce the same action — we rely on guardrails to break loops)                }                is CriticDecision.Stop -> {                    Timber.tag("NOUS.L5").i(                        "Workflow %s stopped: %s (status=%s)",                        workflowId, criticDecision.reason, criticDecision.status,                    )                    // If critic didn't produce a final answer, try best-effort partial extraction                    val effectiveFinalAnswer = criticDecision.finalAnswer                        ?: if (criticDecision.status != WorkflowStatus.COMPLETED) {                            extractPartialAnswer(traceBuilder.getSteps())                        } else null                    val trace = traceBuilder.build(                        finalStatus = criticDecision.status,                        finalAnswer = effectiveFinalAnswer,                        failureReason = if (criticDecision.status == WorkflowStatus.COMPLETED) null else criticDecision.reason,                    )                    // Brain orchestrator (Step 2.8) will emit BrainRequestCompleted                    // with the full BrainTrace. Here we just return the workflow trace.                    return Result.Success(                        data = AgenticOutput(                            trace = trace,                            skillOutput = if (criticDecision.status == WorkflowStatus.COMPLETED && effectiveFinalAnswer != null) {                                SkillOutput.Success(                                    message = effectiveFinalAnswer,                                    data = mapOf(                                        "workflow_id" to workflowId,                                        "steps" to trace.stepCount.toString(),                                        "cost_usd" to trace.totalCostUsd.toString(),                                    ),                                )                            } else if (effectiveFinalAnswer != null) {                                // Failed but have partial answer                                SkillOutput.Partial(                                    message = effectiveFinalAnswer,                                    warnings = listOf("Workflow stopped: ${criticDecision.reason}"),                                )                            } else {                                SkillOutput.Failure(                                    error = AppError.Unknown(correlationId = correlationId),                                    userMessage = "Workflow failed: ${criticDecision.reason}",                                )                            },                        ),                        correlationId = correlationId,                        durationNanos = System.nanoTime() - startNanos,                    )                }            }        }    }    /**     * Extract best-effort partial answer from completed steps (spec §7).     *     * When a workflow fails (max steps, loop, planner failure, etc.), the     * orchestrator extracts the last successful tool/LLM output as a partial     * answer. This is shown to the user as a "best-effort" result instead of     * a hard failure.     *     * @return the last successful observation's output, or null if no steps succeeded     */    private fun extractPartialAnswer(steps: List<WorkflowStep>): String? {        // Walk backwards through steps, find the last successful observation        for (step in steps.asReversed()) {            val observation = step.observation ?: continue            val output = when (observation) {                is AgenticStepResult.ToolSuccess -> observation.output                is AgenticStepResult.LlmSuccess -> observation.text                is AgenticStepResult.FinalAnswerProduced -> observation.answer                is AgenticStepResult.ToolFailure -> null                is AgenticStepResult.LlmFailure -> null            }            if (output != null && output.isNotBlank()) {                return output            }        }        return null    }    companion object {        /**         * Check whether [intent] should trigger an agentic workflow.         *         * Per spec §6.2: Layer 5 is NOT a fallback — it is invoked only when         * the user's intent is explicitly multi-step ([Intent.MultiStep]) or         * when the planner detects compound intent ([Intent.Compound]).         *         * Called by the brain orchestrator (Step 2.8) before invoking Layer 5.         *         * @return true if agentic is appropriate for this intent         */        fun shouldInvoke(intent: com.roshan.persona.brain.intent.Intent): Boolean {            return intent is com.roshan.persona.brain.intent.Intent.MultiStep ||                intent is com.roshan.persona.brain.intent.Intent.Compound        }    }}/** * Output of an agentic workflow. */data class AgenticOutput(    /** Full audit log of the workflow. */    val trace: WorkflowTrace,    /** The final skill output (Success or Failure) to return to the brain. */    val skillOutput: SkillOutput,)